const D = { energy:.6, scale:1, density:.5, speed:1, hue:38, x:.5, y:.94, head:.5, pose:'standing', style:'engraving', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7) * 43758.5453; return s - Math.floor(s); };
const sty = P.style, pose = P.pose;
const EN = cl(P.energy,0,1), SC = cl(P.scale,.3,2.2), DN = cl(P.density,0,1);
const HD = cl(P.head,0,1), AL = cl(P.alpha,0,100)/100;

if (S.lastT == null || K.t < S.lastT) S.lastT = K.t;
let dt = K.t - S.lastT; S.lastT = K.t;
if (!(dt >= 0) || dt > .25) dt = 1/60;
const SP = cl(P.speed,.05,4);
S.tt = (S.tt || 0) + dt*SP;
const T = S.tt;

// ---- wind: incommensurate, so the silhouette never returns to a pose ------
const gust = .9*Math.sin(T*.61) + .5*Math.sin(T*1.43 + 1.7) + .32*Math.sin(T*2.29)
           + .42*Math.sin(T*.197 + .6);
const squall = .5 + .5*Math.sin(T*.083 + 1.1);              // slow weather over minutes

// ---- pose ----------------------------------------------------------------
let bend0, windAmp, whip, shed, spread;
if (pose === 'bowed')        { bend0 = .58; windAmp = .15; whip = .05; shed = .5; spread = .9; }
else if (pose === 'seeding') { bend0 = .18; windAmp = .22; whip = .10; shed = 3.4; spread = 1.25; }
else if (pose === 'thrash')  { bend0 = .10; windAmp = .54; whip = .34; shed = 1.9; spread = 1.1; }
else                         { bend0 = .07; windAmp = .17; whip = .06; shed = .8; spread = 1; }

// total lean at the apex — this is what displaces the silhouette
const wind = gust*(.35 + .65*squall) + A.lowmid*1.1 + A.bass*.5;
const bend = bend0*(1 + .3*Math.sin(T*.31))
           + windAmp*(.4 + 1.5*EN)*wind
           + whip*(K.pulse*K.intensity + A.bass*.7)*(.4 + EN);

// ---- geometry ------------------------------------------------------------
const HGT = u*.475*SC;                                      // hero: 0.40-0.55 x min(w,h)
const bxx = P.x*width, byy = P.y*height;
const NS = 16;
const SX = [], SY = [], SA = [];
{ let px2 = 0, py2 = 0;
  for (let q=0;q<=NS;q++){
    const s = q/NS;
    const th = bend*Math.pow(s, 1.55)                        // curvature gathers toward the apex
             + Math.sin(T*2.7 + s*3.4)*.014*EN;              // fine tremor in the dry tissue
    SX.push(px2); SY.push(py2); SA.push(th);
    if (q < NS) { px2 += Math.sin(th)*HGT/NS; py2 -= Math.cos(th)*HGT/NS; }
  }
}
const hx = SX[NS], hy = SY[NS], hAng = SA[NS];
const R = HGT*(.085 + .085*HD);                             // capitulum radius
const HL = R*(1.7 - HD*.35);                                // capitulum length

// ---- style ---------------------------------------------------------------
const H = P.hue;
let mass_h, mass_s, mass_b, lite_h, lite_s, lite_b, mode;
if (sty === 'cyanotype') { mode = 1; mass_h = 214; mass_s = 40; mass_b = 34; lite_h = 210; lite_s = 4; lite_b = 99; }
else if (sty === 'xray') { mode = 2; mass_h = H; mass_s = 48; mass_b = 30; lite_h = H; lite_s = 22; lite_b = 98; }
else if (sty === 'silhouette') { mode = 3; mass_h = (H*.2 + 18) % 360; mass_s = 40; mass_b = 11; lite_h = mass_h; lite_s = 30; lite_b = 26; }
else { mode = 0; mass_h = (H + 348) % 360; mass_s = 46; mass_b = 15; lite_h = (H + 6) % 360; lite_s = 26; lite_b = 88; }
const LIT = -2.25;                                           // fixed key light, upper-left

// ---- pappus pool: florets detach and drift, the head refills -------------
const NPAP = 22;                                            // 3 of these can share a stage
if (!S.pap || S.pap.length !== NPAP || S.seedUsed !== sd) {
  S.seedUsed = sd; S.pap = [];
  for (let i=0;i<NPAP;i++) S.pap.push({ f: fr(i*7.3), sp: .4 + fr(i*3.1)*.9, ph: fr(i*5.7)*6.28,
    ix: (fr(i*9.1)-.5)*1.7, ang: fr(i*2.3)*6.28 });
}
for (let i=0;i<NPAP;i++) { const p = S.pap[i];
  p.f += dt*SP*shed*p.sp*.055*(.4 + .8*EN)*(.5 + .8*squall);
