  else if (mode === 2) { noStroke(); fill(mass_h, 50, 44, 17*AL); }
  else { noStroke(); fill(mass_h, mass_s, mass_b + 4, 96*AL); }
  beginShape();                                              // a toothed, spine-tipped lamina
  for (let q=0;q<=22;q++){ const v = q/22;
    const w2 = L*.15*Math.pow(Math.sin(Math.PI*Math.pow(v,.7)), .7);
    const ph2 = v*nT, saw = ph2 - Math.floor(ph2);
    vertex(L*v, -(w2*(1 + saw*.9) + (saw > .82 ? L*.03 : 0))); }
  for (let q=22;q>=0;q--){ const v = q/22;
    const w2 = L*.15*Math.pow(Math.sin(Math.PI*Math.pow(v,.7)), .7);
    const ph2 = v*nT + .5, saw = ph2 - Math.floor(ph2);
    vertex(L*v, (w2*(1 + saw*.9) + (saw > .82 ? L*.03 : 0))); }
