  if (mode === 0) {                                          // white-line engraving: form from hatching
    stroke(lite_h, lite_s, lite_b, 34*AL); strokeWeight(Math.max(.4, L*.007));
    for (let q=1;q<9;q++){ const v = q/9.4;
      const w2 = L*.15*Math.pow(Math.sin(Math.PI*Math.pow(v,.7)), .7);
      line(L*v, -w2*.5, L*v + L*.05, w2*.5); }
    stroke(lite_h, lite_s - 8, lite_b, 62*AL); strokeWeight(Math.max(.5, L*.012));
    line(L*.02, 0, L*.95, 0);                                // the pale midrib catches the key light
  } else if (mode === 3) { /* pure mass, no interior */ }
  else if (mode === 1) { stroke(214, 30, 70, 30*AL); strokeWeight(Math.max(.4, L*.009)); line(0, 0, L*.9, 0); }
  else if (mode === 2) { stroke(mass_h, 34, 96, 24*AL); strokeWeight(Math.max(.4, L*.01)); line(0, 0, L*.9, 0); }
