else if (mode === 2) stroke(mass_h, 46, 60, 30*AL);
else stroke(mass_h, mass_s, mass_b, 100*AL);
strokeWeight(stW);
beginShape(); for (let q=0;q<=NS;q++) vertex(SX[q], SY[q]); endShape();
if (mode === 0 || mode === 1) {                              // ribs — the stalk is fluted, not a tube
  for (let rb=-1; rb<=1; rb++) {
    if (mode === 1) stroke(214, 34, 66, 26*AL); else stroke(lite_h, lite_s, lite_b, rb === -1 ? 60*AL : 24*AL);
    strokeWeight(Math.max(.4, stW*(rb === -1 ? .17 : .1)));
    beginShape();
    for (let q=0;q<=NS;q++){ const th = SA[q], nx = Math.cos(th), ny = Math.sin(th);
      vertex(SX[q] + nx*stW*.3*rb, SY[q] + ny*stW*.3*rb); }
    endShape();
  }
}
if (mode === 0) {                                            // cross-hatched dry tissue
  stroke(lite_h, lite_s, lite_b, 22*AL); strokeWeight(Math.max(.35, stW*.08));
  for (let q=1;q<NS;q++){ const th = SA[q], nx = Math.cos(th), ny = Math.sin(th);
    line(SX[q] - nx*stW*.42, SY[q] - ny*stW*.42, SX[q] + nx*stW*.42 + Math.sin(th)*stW*.5,
         SY[q] + ny*stW*.42 - Math.cos(th)*stW*.5); }
}

// ---- capitulum: imbricated bracts on a golden-angle spiral over an ovoid --
push(); translate(hx, hy); rotate(hAng);
const NB = Math.round(34 + DN*26);
