  const phi = k*2.39996 + T*.021, rr = R*.42*Math.sqrt((k + .4)/nSeat);
  const sx = rr*Math.cos(phi), sy = -HL*.44*ct + rr*Math.sin(phi)*st2;
  const tr = Math.sin(T*(2.9 + (k%4)*.4) + k)*(.03 + .1*EN)*R;
  if (mode === 1) stroke(lite_h, 2, 100, 60*AL);
  else if (mode === 2) stroke(mass_h, 16, 100, 22*AL);
  else if (mode === 3) stroke(mass_h, mass_s, mass_b + 16, 70*AL);
  else stroke(lite_h, 10, 96, 54*AL);
  strokeWeight(Math.max(.35, R*.014));
  for (let q=0;q<5;q++){ const a2 = -Math.PI*.5 + (q/4 - .5)*1.5 + tr*.06;
    line(sx, sy, sx + Math.cos(a2)*R*.32 + tr, sy + Math.sin(a2)*R*.32); }
}
